from html.parser import HTMLParser
from pathlib import Path
VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]
        self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append((tag,self.getpos()))
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack:
            self.errors.append(f'unexpected </{tag}> at {self.getpos()}')
            return
        if self.stack[-1][0]!=tag:
            self.errors.append(f'expected </{self.stack[-1][0]}> at {self.stack[-1][1]}, got </{tag}> at {self.getpos()}')
            while self.stack and self.stack[-1][0]!=tag:
                self.stack.pop()
            if self.stack: self.stack.pop()
        else:
            self.stack.pop()
c=Checker(); c.feed(Path('index.html').read_text()); c.close()
print('HTML nesting errors:', c.errors or 'none')
print('Unclosed:', c.stack or 'none')
